// Carrot Revolt Labs · Geometry Nodes · the four labs: steps, explanations, live checklists, starters and solutions.
import { makeNode, makeLink, expose, evaluate, MAT, isField } from './core.js';
import { L } from './docs.js';
export { L };

const D = Math.PI / 180;
/* ── Graph builders ── */
const G = (ix = -260, iy = 0, ox = 400, oy = 0) => ({ nodes: [makeNode('input', 'GroupInput', ix, iy), makeNode('output', 'GroupOutput', ox, oy)], links: [], exposed: [] });
const add = (g, id, type, x, y, params) => { g.nodes.push(makeNode(id, type, x, y, params)); return id; };
const ln = (g, a, out, b, input) => { g.links.push(makeLink(a, out, b, input)); };
const out = (g, x, y) => { const o = g.nodes.find(n => n.id === 'output'); o.x = x; o.y = y; };

/* ── Helpers for the checklists ── */
const N = (g, type) => g.nodes.filter(n => n.type === type);
const node = (g, id) => g.nodes.find(n => n.id === id);
export function reaches(g, from, to = 'output') { const seen = new Set(), st = [from]; while (st.length) { const id = st.pop(); if (id === to) return true; if (seen.has(id)) continue; seen.add(id); g.links.filter(l => l.from === id).forEach(l => st.push(l.to)); } return false; }
const live = (g, type) => N(g, type).filter(n => reaches(g, n.id) && !n.muted);
const linkInto = (g, id, input) => g.links.find(l => l.to === id && l.input === input);
const srcType = (g, id, input) => { const l = linkInto(g, id, input); return l ? node(g, l.from)?.type : null; };
// The value that arrives at an input, as the interpreter calculated it.
const arriving = (g, r, id, input) => { const l = linkInto(g, id, input); return l ? r.memo.get(`${l.from}:${l.out}`) : undefined; };
const depsAt = (g, r, id, input) => { const v = arriving(g, r, id, input); return isField(v) ? [...v.deps] : []; };
// Mesh islands (connected parts) with their bounding boxes.
export function islands(mesh) {
  if (!mesh) return [];
  const parent = mesh.verts.map((_, i) => i), find = i => { while (parent[i] !== i) i = parent[i] = parent[parent[i]]; return i; };
  for (const f of mesh.faces) for (let i = 1; i < f.length; i++) parent[find(f[i])] = find(f[0]);
  const boxes = new Map();
  mesh.verts.forEach((v, i) => { const k = find(i), b = boxes.get(k) || { min: [Infinity, Infinity, Infinity], max: [-Infinity, -Infinity, -Infinity], n: 0 }; for (let j = 0; j < 3; j++) { b.min[j] = Math.min(b.min[j], v[j]); b.max[j] = Math.max(b.max[j], v[j]); } b.n++; boxes.set(k, b); });
  return [...boxes.values()].map(b => ({ ...b, size: b.max.map((v, j) => v - b.min[j]) }));
}
// Bounding box of every instance, with its transform applied.
export function instanceBoxes(geo) {
  return geo.instances.map(s => {
    const b = { min: [Infinity, Infinity, Infinity], max: [-Infinity, -Infinity, -Infinity] };
    const walk = (gg, m) => { gg.mesh?.verts.forEach(v => { const p = MAT.point(m, v); for (let j = 0; j < 3; j++) { b.min[j] = Math.min(b.min[j], p[j]); b.max[j] = Math.max(b.max[j], p[j]); } }); gg.instances.forEach(c => walk(c.geometry, MAT.mul(m, c.matrix))); };
    walk(s.geometry, s.matrix); return b;
  });
}
const range = r => r.stats.maxZ - r.stats.minZ;
const goal = (text, test, optional = false) => ({ text, test, optional });
const step = o => o;

/* ════════════ GN 01 · Geometry flow ════════════ */
const f1 = {
  start: () => G(-260, 40, 340, 40),
  plain() { const g = f1.start(); ln(g, 'input', 'Geometry', 'output', 'Geometry'); return g; },
  moved() { const g = G(-260, 40, 420, 40); add(g, 'move', 'TransformGeometry', 0, 0, { Translation: [0, 0, 1.5], Rotation: [0, 0, 45 * D] }); ln(g, 'input', 'Geometry', 'move', 'Geometry'); ln(g, 'move', 'Geometry', 'output', 'Geometry'); return g; },
  joined() { const g = G(-260, 40, 680, 60); add(g, 'move', 'TransformGeometry', 0, 0, { Translation: [0, 0, 1.5], Rotation: [0, 0, 45 * D] }); add(g, 'cube', 'Cube', -260, 380); add(g, 'join', 'JoinGeometry', 440, 60); ln(g, 'input', 'Geometry', 'move', 'Geometry'); ln(g, 'move', 'Geometry', 'join', 'Geometry'); ln(g, 'cube', 'Mesh', 'join', 'Geometry'); ln(g, 'join', 'Geometry', 'output', 'Geometry'); return g; },
  table() {
    const g = G(-300, 40, 1300, 140);
    add(g, 'top', 'Cube', -40, 0, { Size: [2.4, 1.4, .12] }); add(g, 'topMove', 'TransformGeometry', 170, 0, { Translation: [0, 0, 1.06] });
    add(g, 'leg', 'Cube', -40, 400, { Size: [.12, .12, 1] });
    [[-1.05, -.55], [1.05, -.55], [-1.05, .55], [1.05, .55]].forEach(([x, y], i) => { add(g, `leg${i + 1}`, 'TransformGeometry', 170 + i * 200, 400, { Translation: [x, y, .5] }); ln(g, 'leg', 'Mesh', `leg${i + 1}`, 'Geometry'); });
    add(g, 'join', 'JoinGeometry', 1080, 140);
    ln(g, 'top', 'Mesh', 'topMove', 'Geometry'); ln(g, 'topMove', 'Geometry', 'join', 'Geometry'); [1, 2, 3, 4].forEach(i => ln(g, `leg${i}`, 'Geometry', 'join', 'Geometry')); ln(g, 'join', 'Geometry', 'output', 'Geometry');
    return g;
  },
  viewed() { const g = f1.table(); add(g, 'viewer', 'Viewer', 1080, 380); ln(g, 'leg2', 'Geometry', 'viewer', 'Geometry'); return g; },
  exposed() { const g = f1.table(); expose(g, 'top', 'Size', 'Tabletop Size'); return g; },
};
const tableShape = r => { const parts = islands(r.geometry.mesh); if (parts.length < 5) return false; const top = parts.reduce((a, b) => (b.size[0] * b.size[1] > a.size[0] * a.size[1] ? b : a)); const legs = parts.filter(p => p !== top && p.size[2] > Math.max(p.size[0], p.size[1]) * 2); return legs.length >= 4 && legs.every(p => p.max[2] <= top.min[2] + .05 && p.min[2] > -.1 && p.min[0] >= top.min[0] - .05 && p.max[0] <= top.max[0] + .05 && p.min[1] >= top.min[1] - .05 && p.max[1] <= top.max[1] + .05); };

/* ════════════ GN 02 · Fields ════════════ */
const f2 = {
  start() { const g = G(-260, 0, 320, 0); ln(g, 'input', 'Geometry', 'output', 'Geometry'); return g; },
  grid() { const g = G(-260, 0, 300, 0); add(g, 'grid', 'Grid', 0, 0, { 'Size X': 6, 'Size Y': 6, 'Vertices X': 12, 'Vertices Y': 12 }); ln(g, 'grid', 'Mesh', 'output', 'Geometry'); return g; },
  index() { const g = f2.grid(); add(g, 'index', 'Index', -40, 260); add(g, 'viewer', 'Viewer', 300, 200); ln(g, 'grid', 'Mesh', 'viewer', 'Geometry'); ln(g, 'index', 'Index', 'viewer', 'Value'); node(g, 'viewer').params.valueType = 'float'; return g; },
  wave() {
    const g = G(-300, 0, 900, 0); add(g, 'grid', 'Grid', -40, 0, { 'Size X': 6, 'Size Y': 6, 'Vertices X': 24, 'Vertices Y': 24 }); add(g, 'set', 'SetPosition', 660, 0);
    add(g, 'index', 'Index', -300, 300); add(g, 'slow', 'Math', -120, 280, { operation: 'Multiply', Value_001: .25 }); add(g, 'sine', 'Math', 80, 300, { operation: 'Sine' }); add(g, 'amp', 'Math', 270, 300, { operation: 'Multiply', Value_001: .4 }); add(g, 'xyz', 'CombineXYZ', 460, 300);
    ln(g, 'grid', 'Mesh', 'set', 'Geometry'); ln(g, 'index', 'Index', 'slow', 'Value'); ln(g, 'slow', 'Value', 'sine', 'Value'); ln(g, 'sine', 'Value', 'amp', 'Value'); ln(g, 'amp', 'Value', 'xyz', 'Z'); ln(g, 'xyz', 'Vector', 'set', 'Offset'); ln(g, 'set', 'Geometry', 'output', 'Geometry'); return g;
  },
  terrain(normal = false, exposed = false) {
    const g = G(-560, 0, 1080, 0); add(g, 'grid', 'Grid', -300, 0, { 'Size X': 6, 'Size Y': 6, 'Vertices X': 24, 'Vertices Y': 24 }); add(g, 'set', 'SetPosition', 840, 0);
    add(g, 'pos', 'Position', -560, 300); add(g, 'sep', 'SeparateXYZ', -380, 300); add(g, 'sinX', 'Math', -180, 250, { operation: 'Sine' }); add(g, 'cosY', 'Math', -180, 420, { operation: 'Cosine' }); add(g, 'mix', 'Math', 10, 300, { operation: 'Multiply' }); add(g, 'amp', 'Math', 200, 300, { operation: 'Multiply', Value_001: .6 });
    ln(g, 'grid', 'Mesh', 'set', 'Geometry'); ln(g, 'pos', 'Position', 'sep', 'Vector'); ln(g, 'sep', 'X', 'sinX', 'Value'); ln(g, 'sep', 'Y', 'cosY', 'Value'); ln(g, 'sinX', 'Value', 'mix', 'Value'); ln(g, 'cosY', 'Value', 'mix', 'Value_001'); ln(g, 'mix', 'Value', 'amp', 'Value'); ln(g, 'set', 'Geometry', 'output', 'Geometry');
    if (normal) { add(g, 'normal', 'Normal', 200, 500); add(g, 'push', 'VectorMath', 420, 300, { operation: 'Scale' }); ln(g, 'normal', 'Normal', 'push', 'Vector'); ln(g, 'amp', 'Value', 'push', 'Scale'); ln(g, 'push', 'Vector', 'set', 'Offset'); }
    else { add(g, 'xyz', 'CombineXYZ', 420, 300); ln(g, 'amp', 'Value', 'xyz', 'Z'); ln(g, 'xyz', 'Vector', 'set', 'Offset'); }
    if (exposed) expose(g, 'amp', 'Value_001', 'Height');
    return g;
  },
};
const setLive = g => live(g, 'SetPosition').find(n => reaches(g, n.id));

/* ════════════ GN 03 · Scatter ════════════ */
const f3 = {
  start() { const g = G(-260, 0, 320, 0); ln(g, 'input', 'Geometry', 'output', 'Geometry'); return g; },
  points() { const g = G(-260, 0, 300, 0); add(g, 'scatter', 'DistributePoints', 0, 0, { Density: 3, Seed: 5 }); ln(g, 'input', 'Geometry', 'scatter', 'Mesh'); ln(g, 'scatter', 'Points', 'output', 'Geometry'); return g; },
  rocks(pick = false, vary = false, mask = false, realize = false) {
    const g = G(-260, 0, realize ? 1000 : 820, 40);
    add(g, 'scatter', 'DistributePoints', 0, 0, { Density: vary ? 1 : 3, Seed: 5 }); add(g, 'rocks', 'CollectionInfo', 0, 280, pick ? { 'Separate Children': true, 'Reset Children': true } : {}); add(g, 'inst', 'InstanceOnPoints', 260, 0, pick ? { 'Pick Instance': true } : {});
    add(g, 'join', 'JoinGeometry', realize ? 780 : 600, 40);
    ln(g, 'input', 'Geometry', 'scatter', 'Mesh'); ln(g, 'scatter', 'Points', 'inst', 'Points'); ln(g, 'rocks', 'Instances', 'inst', 'Instance');
    if (realize) { add(g, 'real', 'RealizeInstances', 520, 0); ln(g, 'inst', 'Instances', 'real', 'Geometry'); ln(g, 'real', 'Geometry', 'join', 'Geometry'); } else ln(g, 'inst', 'Instances', 'join', 'Geometry');
    ln(g, 'input', 'Geometry', 'join', 'Geometry'); ln(g, 'join', 'Geometry', 'output', 'Geometry');
    if (vary) {
      add(g, 'size', 'RandomValue', 0, 470, { Min: .4, Max: 1.1, Seed: 2 }); add(g, 'turn', 'RandomValue', 0, 680, { type: 'Vector', Min_vec: [0, 0, 0], Max_vec: [0, 0, 6.283], Seed: 3 });
      ln(g, 'size', 'Value', 'inst', 'Scale'); ln(g, 'turn', 'Value', 'inst', 'Rotation');
    }
    if (mask) { add(g, 'pos', 'Position', -620, 260); add(g, 'sep', 'SeparateXYZ', -450, 260); add(g, 'above', 'Math', -260, 300, { operation: 'Greater Than', Value_001: .1 }); ln(g, 'pos', 'Position', 'sep', 'Vector'); ln(g, 'sep', 'Z', 'above', 'Value'); ln(g, 'above', 'Value', 'scatter', 'Selection'); expose(g, 'scatter', 'Density', 'Rock Density'); }
    return g;
  },
};
const instNode = g => live(g, 'InstanceOnPoints')[0];
const distinct = (list, k = 2) => new Set(list.map(v => v.toFixed(k))).size;

/* ════════════ GN 04 · Curves ════════════ */
const f4 = {
  start: () => G(-260, 0, 320, 0),
  line() { const g = G(-260, 0, 300, 0); add(g, 'line', 'CurveLine', 0, 0, { End: [6, 0, 0] }); ln(g, 'line', 'Curve', 'output', 'Geometry'); return g; },
  rail() { const g = G(-260, 0, 520, 0); add(g, 'line', 'CurveLine', 0, 0, { End: [6, 0, 0] }); add(g, 'profile', 'CurveCircle', 0, 360, { Radius: .05, Resolution: 12 }); add(g, 'sweep', 'CurveToMesh', 260, 0); ln(g, 'line', 'Curve', 'sweep', 'Curve'); ln(g, 'profile', 'Curve', 'sweep', 'Profile Curve'); ln(g, 'sweep', 'Mesh', 'output', 'Geometry'); return g; },
  fence(raised = false, bent = false, exposed = false) {
    const g = G(-300, 0, 1180, 60);
    if (bent) add(g, 'curve', 'QuadraticBezier', -40, 0, { Start: [-3, 0, 0], Middle: [0, 3, 0], End: [3, 0, 0] }); else add(g, 'curve', 'CurveLine', -40, 0, { End: [6, 0, 0] });
    add(g, 'profile', 'CurveCircle', -40, 380, { Radius: .05, Resolution: 12 }); add(g, 'sweep', 'CurveToMesh', 200, 0);
    add(g, 'points', 'CurveToPoints', 200, 160, { Count: 7 }); add(g, 'post', 'Cube', 200, 400, { Size: [.12, .12, 1.2] }); add(g, 'postUp', 'TransformGeometry', 410, 400, { Translation: [0, 0, .6] });
    add(g, 'inst', 'InstanceOnPoints', 640, 160); add(g, 'join', 'JoinGeometry', 960, 60);
    ln(g, 'curve', 'Curve', 'sweep', 'Curve'); ln(g, 'profile', 'Curve', 'sweep', 'Profile Curve'); ln(g, 'curve', 'Curve', 'points', 'Curve'); ln(g, 'post', 'Mesh', 'postUp', 'Geometry'); ln(g, 'points', 'Points', 'inst', 'Points'); ln(g, 'postUp', 'Geometry', 'inst', 'Instance'); ln(g, 'inst', 'Instances', 'join', 'Geometry');
    if (raised) { add(g, 'railUp', 'TransformGeometry', 410, -360, { Translation: [0, 0, 1.05] }); ln(g, 'sweep', 'Mesh', 'railUp', 'Geometry'); ln(g, 'railUp', 'Geometry', 'join', 'Geometry'); } else ln(g, 'sweep', 'Mesh', 'join', 'Geometry');
    ln(g, 'join', 'Geometry', 'output', 'Geometry');
    if (exposed) { expose(g, 'curve', 'Middle', 'Bend'); expose(g, 'points', 'Count', 'Posts'); expose(g, 'profile', 'Radius', 'Rail Radius'); }
    return g;
  },
};
const railMesh = r => islands(r.geometry.mesh).filter(p => Math.max(p.size[0], p.size[1]) > 1);

